'use strict';
const preferenceKey='everymart-preferences-v1';
let savedPreferences={};try{savedPreferences=JSON.parse(localStorage.getItem(preferenceKey)||'{}')}catch{}
if(!savedPreferences||typeof savedPreferences!=='object'||Array.isArray(savedPreferences))savedPreferences={};
let records=[],role=['group','store'].includes(savedPreferences.role)?savedPreferences.role:'group',plan=['trial','mature'].includes(savedPreferences.plan)?savedPreferences.plan:'trial',query='',category='all',priceType='all',scope='candidate',page=1,dialogTrigger=null;
const main=document.querySelector('#main'),dialog=document.querySelector('#detail');
const labels={overview:'经营总览',products:'商品研究',suppliers:'供货渠道',store:'门店执行'};
const types={wholesale:'批发参考',retail:'零售参考',promo:'条件促销',nonprice:'规格 / 渠道'};
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=u=>{try{const x=new URL(u);return ['http:','https:'].includes(x.protocol)?x.href:'#'}catch{return '#'}};
const fmt=n=>Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2,minimumFractionDigits:2});
function group(o){let n=o.task_id;if(n>=35&&n<=41||n===65)return '水饮咖啡';if(n>=42&&n<=44)return '乳品';if(n>=45&&n<=50||n===64)return '零食';if(n===51||n===52)return '方便速食';if(n>=53&&n<=56)return '鲜食原料';if(n>=57&&n<=59)return '冲调';if(n===60||n===61)return '母婴';if(n===62||n===63)return '文具';if(n===66||n===67)return '日百应急';if(n===68||n===69)return '个护纸品';if(n===70)return '酒类';if(n===71)return '冰品';return '渠道与行业'}
const intro=(title,sub,en)=>'<div class="page-top"><div><div class="eyebrow">'+en+'</div><h1>'+title+'</h1><p>'+sub+'</p></div><span class="date">研究更新<br><strong>2026.09.11</strong></span></div>';
const stats=()=>'<div class="stats">'+[['400','个','单店商品位置','试点配额建议'],['248','条','公开价格记录','含零售、促销与历史参考'],['43','条','批发比价候选','交易条件与到店价待核'],['50','项','首批巡店标品','同规格采价，待门店执行']].map(x=>'<div class="stat"><div class="stat-label">'+x[2]+'</div><div class="stat-value">'+x[0]+'<small>'+x[1]+'</small></div><div class="stat-note">'+x[3]+'</div></div>').join('')+'</div>';
const plans=[['水饮',110,95],['零食',60,55],['香烟',35,35],['方便速食',35,30],['乳品',30,25],['酒类',30,30],['个护纸品',30,30],['日百应急',25,25],['鲜食 / 短保',20,50],['冰品',15,15],['其他',10,10]];
function allocation(){return '<div class="panel"><div class="panel-head"><h2>400 SKU 品类配置</h2><div class="switch" aria-label="配额方案"><button data-plan="trial" aria-pressed="'+(plan==='trial')+'" class="'+(plan==='trial'?'active':'')+'">试点阶段</button><button data-plan="mature" aria-pressed="'+(plan==='mature')+'" class="'+(plan==='mature'?'active':'')+'">日配成熟后</button></div></div><div class="allocation">'+plans.map(x=>{let v=x[plan==='trial'?1:2];return '<div class="bar-row"><span>'+x[0]+'</span><div class="bar-track"><div class="bar-fill" style="width:'+v/110*100+'%"></div></div><span class="bar-number">'+v+'</span></div>'}).join('')+'</div><div class="panel-note">'+(plan==='trial'?'鲜食先配置 20 个位置，以 6 个热柜品项开始验证。':'鲜食扩展至 50 位；从水饮、乳品、零食及速食调回 30 位。')+'<br>配额总计 400，属于方案建议；未确认供货的位置保留待选。</div></div>'}
function priorities(){return '<div class="panel"><div class="panel-head"><h2>'+(role==='group'?'本阶段决策重点':'店长优先事项')+'</h2><span class="chip warm">四周试点</span></div>'+[['统一价格口径','围绕 50 个同规格标品，取得实售价、条码与有效到店报价。','门店执行','store'],['先验证鲜食，再扩大日配','从 6 个热柜品项开始，记录到货、出品、销售及未售报损。','查看供应线索','suppliers'],['以实际动销决定取舍','结合缺货、有货天数和贡献毛利，形成保留、调价、降量与替换清单。','查阅商品研究','products']].map((x,i)=>'<div class="priority"><span class="number">0'+(i+1)+'</span><div><h3>'+x[0]+'</h3><p>'+x[1]+'</p><a class="text-link" href="#'+x[3]+'">'+x[2]+' ↗</a></div></div>').join('')+'</div>'}
function overview(){
const briefs=[['鲜食供应','核实本地央厨供货','伊森诚品列有便利店供应与定制服务，重点确认起订、日配与退换。','suppliers','供货渠道'],['采购比价','把价格与条件放在一起','同箱规核价，同时记录起送、运费、会员条件及有效期。','products','商品研究'],['商圈竞争','按同商圈、同规格采价','优先观察常买标品与早餐热食组合，不用历史宣传代替门店实况。','store','采价安排']];
const picks=[['56','56-10','伍氏黄焖鸡料理包','200g / 袋','5.35–5.50','40袋/箱；1–9箱220元，10箱起214元','成都发货，冷链运费待核'],['47','47-N03','甘源蟹黄蚕豆','75g / 袋','3.10','公开批发挂牌；页面标注不退货','成都经营地址，配送范围待核'],['37','O01','芬达橙味','500ml / 瓶','2.24','24瓶/箱，53.64元；含税含运','酒店20件起送，便利店适用性待核']];
main.innerHTML=intro(role==='group'?'经营总览':'门店经营准备','400位商品配置 · 公开价格依据 · 四周试点安排','OPERATIONS BRIEF')+stats()+'<div class="overview-grid">'+allocation()+priorities()+'<div class="research-briefs">'+briefs.map((x,i)=>'<article class="brief"><span class="kicker">0'+(i+1)+' / '+x[0]+'</span><h3>'+x[1]+'</h3><p>'+x[2]+'</p><a class="text-link" href="#'+x[3]+'">'+x[4]+' ↗</a></article>').join('')+'</div></div><section class="price-preview"><div class="section-head"><h2>重点核价线索</h2><a class="preview-link" href="#products">全部商品研究 ↗</a></div><div class="table-wrap"><table><thead><tr><th>商品 / 单件规格</th><th>折算参考价</th><th>原始购买条件</th><th>门店适用性</th></tr></thead><tbody>'+picks.map(x=>'<tr class="product-row" data-key="'+x[0]+':'+x[1]+'" tabindex="0" aria-label="查看'+x[2]+'依据"><td><span class="preview-item">'+x[2]+'</span><span class="preview-note">'+x[3]+'</span></td><td><span class="price">'+x[4]+'</span><span class="price-unit"> 元</span></td><td class="source-cell">'+x[5]+'</td><td class="source-cell">'+x[6]+'</td></tr>').join('')+'</tbody></table></div><p class="panel-note">以上为2026-09-11采集的公开线索，有效期未明示。折算单件价不表示允许单件采购；点击查看原始证据。</p></section>';
}
function products(){main.innerHTML=intro('商品研究','先核规格与价格条件，再判断商品是否适合门店。','PRODUCT INTELLIGENCE')+'<div class="notice">当前展示公开研究快照。可比候选已排除部分异常、模糊和过旧记录，仍需确认有效期与门店配送。</div><div class="toolbar"><input class="search" id="search" type="search" placeholder="搜索商品、品牌或供应商" aria-label="搜索商品、品牌或供应商" value="'+escapeHtml(query)+'"><select id="category" aria-label="选择品类"><option value="all">全部品类</option>'+[...new Set(records.map(group))].map(x=>'<option '+(category===x?'selected':'')+'>'+x+'</option>').join('')+'</select><select id="price-type" aria-label="选择价格性质"><option value="all">全部价格类型</option>'+Object.entries(types).map(([k,v])=>'<option value="'+k+'" '+(priceType===k?'selected':'')+'>'+v+'</option>').join('')+'</select><select id="scope" aria-label="选择资料范围"><option value="candidate" '+(scope==='candidate'?'selected':'')+'>可比候选</option><option value="all" '+(scope==='all'?'selected':'')+'>全部研究记录</option></select></div><div id="results"></div>';renderResults();document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;page=1;renderResults()});for(let [id,set] of [['category',v=>category=v],['price-type',v=>priceType=v],['scope',v=>scope=v]])document.getElementById(id).addEventListener('change',e=>{set(e.target.value);page=1;renderResults()})}
function filtered(){return records.filter(o=>(scope==='all'||o.candidate_for_comparison)&&(category==='all'||group(o)===category)&&(priceType==='all'||o.price_type===priceType)&&(!query||[o.sku,o.spec,o.supplier].join(' ').toLowerCase().includes(query.toLowerCase().trim())))}
function renderResults(){const r=filtered(),pages=Math.max(1,Math.ceil(r.length/16));page=Math.min(page,pages);document.getElementById('results').innerHTML='<div class="section-head"><span class="small">共 '+r.length+' 条证据记录 · 同一商品可能有多个来源</span><span class="small">点击商品查看依据</span></div><div class="table-wrap"><table><thead><tr><th>商品 / 规格</th><th>价格参考</th><th>价格性质</th><th>供应商 / 来源</th><th>资料状态</th></tr></thead><tbody>'+r.slice((page-1)*16,page*16).map(o=>'<tr class="product-row" data-key="'+o.task_id+':'+escapeHtml(o.id)+'" tabindex="0" aria-label="查看'+escapeHtml(o.sku)+'"><td><div class="product-name">'+escapeHtml(o.sku)+'</div><div class="product-spec">'+escapeHtml(o.spec)+'</div></td><td><div class="price">'+(o.normalized_price!=null?fmt(o.normalized_price):'—')+'</div><div class="price-unit">'+escapeHtml(o.normalized_price!=null?o.normalized_unit:'暂无可用价格')+'</div></td><td><span class="chip">'+(types[o.price_type]||'资料线索')+'</span></td><td class="source-cell">'+escapeHtml(o.supplier||o.source_title)+'</td><td><span class="status '+(!o.candidate_for_comparison?'muted':'')+'">'+(o.candidate_for_comparison?'候选 · 条件待核':'仅供研究')+'</span></td></tr>').join('')+'</tbody></table>'+(!r.length?'<div class="empty"><h3>未找到匹配记录</h3><p>试试更短的商品名，或切换为全部研究记录。</p><button class="btn" id="reset" style="margin-top:18px">清除筛选</button></div>':'')+'</div><div class="pager"><span>价格单位按原资料展示，具体箱规与购买条件见详情。</span><div class="pager-buttons"><button class="btn" id="prev" '+(page===1?'disabled':'')+'>上一页</button><span style="padding:9px">'+page+' / '+pages+'</span><button class="btn" id="next" '+(page===pages?'disabled':'')+'>下一页</button></div></div>';document.getElementById('prev').onclick=()=>{page--;renderResults()};document.getElementById('next').onclick=()=>{page++;renderResults()};document.getElementById('reset')?.addEventListener('click',()=>{query='';category=priceType='all';scope='all';page=1;products()})}
function showRecord(key){const o=records.find(x=>x.task_id+':'+x.id===key);if(!o)return;showDialog('商品依据 / '+o.task_id+' · '+o.id,'<span class="chip">'+group(o)+'</span><h2>'+escapeHtml(o.sku)+'</h2><p>'+escapeHtml(o.spec)+'</p><div class="dialog-price">'+(o.normalized_price!=null?fmt(o.normalized_price):'暂无可用价格')+'</div><p>'+escapeHtml(o.normalized_price!=null?o.normalized_unit:'保留规格或渠道线索')+' · '+(types[o.price_type]||'研究参考')+'</p><dl>'+[['原始报价',o.raw_price!=null?o.raw_price+' '+o.raw_unit:'未获得'],['供应商 / 信息来源',o.supplier||o.source_title],['起订及交易条件',(o.moq||'起订量未明示')+'；'+(o.conditions||'具体条件待核实')],['成都配送',o.chengdu_delivery||'未确认'],['来源日期',o.source_date||'来源未标明；不能以采集日代替生效日'],['采集日期',o.collected_at],['证据摘要',o.evidence],['使用边界',(o.review_flags||[]).join('；')||'仍需确认实际采购条件']].map(([k,v])=>'<dt>'+k+'</dt><dd>'+escapeHtml(v)+'</dd>').join('')+'</dl><a class="btn primary" target="_blank" rel="noopener noreferrer" href="'+escapeHtml(safeUrl(o.source_url))+'">查看公开来源 ↗</a>')}
const supply=[['鲜食成品','麦吉可 · 伊森诚品','成都龙泉中央鲜食工厂，官网列有便当、饭团、三明治及面向便利店的供应和定制服务。','成品价盘、起订量、日配频次及退换责任','https://www.magick-scm.com/'],['冷冻料理包','成都海通森美','伍氏黄焖鸡 200g×40袋，公开箱价 214–220 元，页面明示成都发货。','报价有效期、冷链运费和批次；米饭与包材另计','https://m.gys.cn/jishifangbianfanl/5062941970.html'],['常温零食','益康食品批发','成都经营地址公开；甘源蟹黄蚕豆75g挂牌3.10元/袋，页面标注不退货。','目标门店配送范围、起订量及有效期','https://yikang66.pospal.cn/home/webstore?cid=2867276'],['综合标品','茶坊村供应链','官网列有成都仓、本地配送及饮料、酒水、零食品牌供货线索。','门店覆盖、品牌授权、商品价盘与实际起送门槛','https://www.teahouses.cn/supply-chain.html'],['冷链服务','成都银犁','官网列有城市配送与冷链仓储业务，可作为配送能力核实入口。','温控记录、班次、区域、费用及赔付规则','https://www.yinli56.com/business.html'],['冻品经销','郫都区江田食品经营部','公开页面列明成都海霸王经营地址及低温肉制品、速冻食品批发配送。','具体品牌、箱规、到店价与剩余保质期','https://www.rfwdp.cn/']];
function suppliers(){main.innerHTML=intro('供货渠道','将供应商线索，推进为明确的商品与配送条件。','SUPPLY NETWORK')+'<div class="notice">以下是公开渠道线索，尚未取得集刻门店的供货承诺或有效报价。供应商与物流服务商分开核实。</div><div class="supplier-grid">'+supply.map(x=>'<article class="panel supplier"><div class="panel-head"><span class="chip">'+x[0]+'</span><span class="small">成都相关线索</span></div><h2>'+x[1]+'</h2><p style="margin-top:12px">'+x[2]+'</p><span class="label">采购需要进一步确认</span><div class="conditions">'+x[3]+'</div><a class="text-link" href="'+x[4]+'" target="_blank" rel="noopener noreferrer">查看公开来源 ↗</a></article>').join('')+'</div><div class="panel-note">来源：第四轮第47、56、72号研究；页面有效期未明示，采集于2026-09-11。以上排序不构成供应商信用评级。</div>'}
function store(){main.innerHTML=intro('门店执行','从一张同规格采价表开始，把研究转化为门店证据。','STORE PLAYBOOK')+'<div class="grid-main"><section class="panel"><div class="panel-head"><h2>第一步 · 50 项标品巡店采价</h2><span class="chip warm">待实采</span></div><p style="font-size:15px">选择同商圈的 7‑11、罗森、全家、红旗与舞东风门店，核对商品条码和规格，分开记录日常价与条件促销。</p><div class="task-list">'+[['先锁定同一商品','记录品牌、口味、净含量与条码；不同包装不合并。'],['再记录价格条件','区分普通价、会员价、叠券价；记下活动日期和适用门店。'],['缺货如实留空','未售卖、缺货和无法确认分开备注，不以估计价补齐。']].map((x,i)=>'<div class="task"><span class="task-index">0'+(i+1)+'</span><div><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div></div>').join('')+'<a class="btn primary" href="store-price-check.csv" download style="margin-top:24px">下载 50 项采价清单 ↓</a><p class="small" style="margin-top:12px">CSV 可用 Excel 打开；报价栏为空，供现场填写。</p></section><section class="panel"><div class="panel-head"><h2>鲜食试点记录重点</h2><span class="chip">6 个热柜品项起步</span></div>'+[['到货','记录批次、成本、剩余保质期及温控情况。'],['出品','按时段记录上柜数量，保证采购与销售单位一致。'],['收尾','记录售罄、缺货与未售报损，不重复扣除整批采购成本。']].map((x,i)=>'<div class="priority"><span class="number">0'+(i+1)+'</span><div><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div></div>').join('')+'</section></div><section class="wide-section"><div class="section-head"><h2>四周试点节奏</h2><span class="small">建议安排 · 尚未启动</span></div><div class="steps">'+[['第 1 周','核价与核供','采购 / 区域运营','完成50项采价、条码与同规格供应商询价。'],['第 2 周','小批试销','试点店长 / 采购','整理400位配置，验证6个热柜品项。'],['第 3 周','检查动销','店长 / 数据负责人','结合有货天数，观察缺货、售罄和报损。'],['第 4 周','决定去留','集团商品负责人','形成保留、调价、降量和替换清单。']].map((x,i)=>'<article class="step"><div class="step-no">0'+(i+1)+'</div><div class="small">'+x[0]+' · '+x[2]+'</div><h3 style="margin:10px 0">'+x[1]+'</h3><p>'+x[3]+'</p></article>').join('')+'</div></section>'}
function savePreferences(){try{localStorage.setItem(preferenceKey,JSON.stringify({role,plan}))}catch{}}
function syncRoleControls(){document.querySelectorAll('[data-role]').forEach(x=>{const active=x.dataset.role===role;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))})}
function showDialog(label,content){dialogTrigger=document.activeElement;document.getElementById('dialog-label').textContent=label;document.getElementById('dialog-body').innerHTML=content;dialog.showModal();document.getElementById('close-dialog').focus()}
function route(){let id=location.hash.slice(1)||'overview';if(!labels[id])id='overview';document.getElementById('breadcrumb').textContent=labels[id];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===id);a.setAttribute('aria-current',a.dataset.nav===id?'page':'false')});({overview,products,suppliers,store}[id])()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-plan]');if(b){plan=b.dataset.plan;savePreferences();route()}const r=e.target.closest('[data-role]');if(r){role=r.dataset.role;savePreferences();syncRoleControls();if(role==='store'){location.hash='store';if(location.hash==='#store')route()}else{location.hash='overview';route()}}const row=e.target.closest('[data-key]');if(row)showRecord(row.dataset.key)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-key]')){e.preventDefault();showRecord(e.target.dataset.key)}});
document.getElementById('close-dialog').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
dialog.addEventListener('close',()=>{const target=dialogTrigger;dialogTrigger=null;const fallback=document.getElementById('about');if(target&&target.isConnected&&typeof target.focus==='function')target.focus();else fallback?.focus()});
document.getElementById('about').onclick=()=>showDialog('数据与使用说明','<span class="eyebrow">RESEARCH NOTES</span><h2>让每项判断，都能回到依据。</h2><p>本展示站基于2026年9月11日的公开研究快照，面向集刻集团运营与门店店长。未接入门店POS或实时库存。</p><dl><dt>商品资料</dt><dd>商品研究页包含第四轮471条证据观察，涵盖价格、规格、供应渠道及行业资料。它们不等于471个独立SKU。</dd><dt>价格记录</dt><dd>第四轮CSV有268行，其中248行含至少一项价格。页面按证据拆分展示，同一商品可能有多条来源，两个数量口径不同。</dd><dt>可比候选</dt><dd>222条观察经过规则初筛，其中43条带批发标签。候选不表示已确认成都配送、交易条件或现行报价。</dd><dt>方案与事实</dt><dd>400 SKU配额、6个热柜品项及四周节奏均为试点建议；50项采价清单尚待客户执行。网页不展示虚构销量、库存或实际毛利。</dd><dt>来源与局限</dt><dd>35–37号早期日志为重建记录，部分已补充复核；其他新引用与保存的检索返回已核对。来源未标日期时，不以采集日代替生效日。</dd></dl>');
